PRAGMA page_size=4096;
PRAGMA encoding='UTF-8';
PRAGMA auto_vacuum=NONE;
PRAGMA journal_mode=MEMORY;
PRAGMA synchronous=FULL;
PRAGMA temp_store=MEMORY;
PRAGMA foreign_keys=ON;
PRAGMA trusted_schema=OFF;
PRAGMA application_id=1162104113;
PRAGMA user_version=1;
CREATE TABLE projection_policy(singleton INTEGER PRIMARY KEY CHECK(singleton=1),projection_schema TEXT NOT NULL CHECK(projection_schema='ergentics_disposal_metrics_v1'),authority_vector TEXT NOT NULL CHECK(authority_vector='00000000'),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0),prose_may_supply_fact INTEGER NOT NULL CHECK(prose_may_supply_fact=0),unavailable_behavior TEXT NOT NULL CHECK(unavailable_behavior='EMPTY_OR_EXPLICIT_ABSTAIN_NO_STALE_FALLBACK')) STRICT;
CREATE TABLE evidence_input(singleton INTEGER PRIMARY KEY CHECK(singleton=1),evidence_projection_id TEXT NOT NULL CHECK(length(evidence_projection_id)=64),evidence_database_sha256 TEXT NOT NULL CHECK(length(evidence_database_sha256)=64),evidence_database_bytes INTEGER NOT NULL CHECK(evidence_database_bytes>0),evidence_relational_export_sha256 TEXT NOT NULL CHECK(length(evidence_relational_export_sha256)=64),adapter_sha256 TEXT NOT NULL CHECK(length(adapter_sha256)=64),lattice_sha256 TEXT NOT NULL CHECK(length(lattice_sha256)=64)) STRICT;
CREATE TABLE rusage_samples(sample_id TEXT PRIMARY KEY CHECK(length(sample_id)=64),source_frame_id TEXT NOT NULL CHECK(length(source_frame_id)=64),source_frame_sha256 TEXT NOT NULL CHECK(length(source_frame_sha256)=64),source_target_id TEXT NOT NULL CHECK(length(source_target_id)=64),target_label TEXT NOT NULL,sample_round INTEGER NOT NULL CHECK(sample_round>=0),pid INTEGER NOT NULL CHECK(pid>0),uniqueid_text TEXT,idversion_text TEXT,sid INTEGER,pgid INTEGER,process_uuid_hex TEXT CHECK(process_uuid_hex IS NULL OR length(process_uuid_hex)=32),rusage_uuid_hex TEXT CHECK(rusage_uuid_hex IS NULL OR length(rusage_uuid_hex)=32),process_start_abstime_text TEXT,raw_buffer_state TEXT NOT NULL CHECK(raw_buffer_state IN('RAW_464_VERIFIED','PARSED_FIELDS_ONLY_RAW_ABSENT','SOURCE_REPORTED_ONLY','ABSTAIN_UNAVAILABLE')),raw_buffer_sha256 TEXT CHECK(raw_buffer_sha256 IS NULL OR length(raw_buffer_sha256)=64),raw_buffer BLOB,generation_join_state TEXT NOT NULL CHECK(generation_join_state IN('EXACT_GENERATION_SESSION_GROUP_UUID_START_JOIN','PARTIAL_JOIN','DRIFT','ABSTAIN')),CHECK((raw_buffer_state='RAW_464_VERIFIED' AND length(raw_buffer)=464 AND raw_buffer_sha256 IS NOT NULL) OR (raw_buffer_state!='RAW_464_VERIFIED' AND raw_buffer IS NULL AND raw_buffer_sha256 IS NULL))) STRICT,WITHOUT ROWID;
CREATE TABLE rusage_fields(sample_id TEXT NOT NULL REFERENCES rusage_samples(sample_id),field_name TEXT NOT NULL,byte_offset INTEGER CHECK(byte_offset IS NULL OR byte_offset>=0),byte_width INTEGER CHECK(byte_width IS NULL OR byte_width>0),unsigned_decimal_text TEXT,unit TEXT NOT NULL,raw_verification_grade TEXT NOT NULL CHECK(raw_verification_grade IN('RAW_464_OFFSET_VERIFIED','PARSED_SOURCE_FIELD_ONLY','SOURCE_REPORTED_ONLY','ABSTAIN_UNAVAILABLE')),source_json_pointer TEXT,PRIMARY KEY(sample_id,field_name)) STRICT,WITHOUT ROWID;
CREATE TABLE metric_intervals(interval_id TEXT PRIMARY KEY CHECK(length(interval_id)=64),before_sample_id TEXT NOT NULL REFERENCES rusage_samples(sample_id),after_sample_id TEXT NOT NULL UNIQUE REFERENCES rusage_samples(sample_id),target_label TEXT NOT NULL,join_state TEXT NOT NULL CHECK(join_state IN('EXACT_GENERATION_SESSION_GROUP_UUID_START_JOIN','DRIFT','ABSTAIN')),timebase_numerator_text TEXT,timebase_denominator_text TEXT,elapsed_minimum_ns_text TEXT,elapsed_estimate_ns_text TEXT,elapsed_maximum_ns_text TEXT,interval_state TEXT NOT NULL CHECK(interval_state IN('VALID_MONOTONIC_COUNTER_INTERVAL','INVALID_COUNTER_REGRESSION','INVALID_TIME_BOUND_ORDER','INVALID_GENERATION_JOIN','ABSTAIN_MISSING_INPUT')),UNIQUE(before_sample_id,after_sample_id),CHECK(before_sample_id!=after_sample_id),CHECK((timebase_numerator_text IS NULL)=(timebase_denominator_text IS NULL)),CHECK(interval_state!='VALID_MONOTONIC_COUNTER_INTERVAL' OR (timebase_numerator_text IS NOT NULL AND timebase_denominator_text IS NOT NULL AND elapsed_minimum_ns_text IS NOT NULL AND elapsed_estimate_ns_text IS NOT NULL AND elapsed_maximum_ns_text IS NOT NULL))) STRICT,WITHOUT ROWID;
CREATE TABLE field_adjudications(adjudication_id TEXT PRIMARY KEY CHECK(length(adjudication_id)=64),interval_id TEXT NOT NULL REFERENCES metric_intervals(interval_id),field_surface TEXT NOT NULL CHECK(field_surface IN('JSON','SQLITE','LEDGER','OVERLAY')),field_name TEXT NOT NULL,source_pointer TEXT NOT NULL,original_lexeme TEXT,verdict TEXT NOT NULL CHECK(verdict IN('VALID_SOURCE_FACT','INVALID_MISLABELED_MACH_ABSOLUTE_TIME_TICKS','INVALID_DERIVED_WITHOUT_TIMEBASE','INVALID_NORMALIZED_COPY','ABSTAIN_NOT_RETAINED')),reason_code TEXT NOT NULL,replacement_metric_name TEXT,UNIQUE(interval_id,field_surface,field_name)) STRICT,WITHOUT ROWID;
CREATE TABLE metric_facts(metric_id TEXT PRIMARY KEY CHECK(length(metric_id)=64),interval_id TEXT NOT NULL REFERENCES metric_intervals(interval_id),metric_name TEXT NOT NULL CHECK(metric_name IN('delta_user_ticks','delta_system_ticks','delta_cpu_ticks','cpu_time_nanoseconds','cpu_percent_lower','cpu_percent_estimated','cpu_percent_upper','delta_energy_nj','delta_energy_joules','delta_energy_ergs','power_w_lower','power_w_estimated','power_w_upper')),bound_kind TEXT NOT NULL CHECK(bound_kind IN('EXACT','LOWER','ESTIMATED','UPPER')),numerator_text TEXT NOT NULL,denominator_text TEXT NOT NULL,unit TEXT NOT NULL,approximation_text TEXT,source_grade TEXT NOT NULL CHECK(source_grade IN('RAW_BUFFER_EXACT_RATIONAL','PARSED_FIELDS_EXACT_RATIONAL','SEALED_OVERLAY_REPORTED','ABSTAIN_UNAVAILABLE')),premise_state TEXT NOT NULL CHECK(premise_state IN('VALID_UNDER_PINNED_TIMEBASE_AND_SCOPE','POSITIVE_KERNEL_TASK_ATTRIBUTED_DELTA_SCOPE_QUALIFIED','ABSTAIN_ZERO_DELTA_NO_POSITIVE_METER_SUPPORT_EVIDENCE','INVALID','ABSTAIN')),source_pointer TEXT NOT NULL,UNIQUE(interval_id,metric_name,bound_kind)) STRICT,WITHOUT ROWID;
CREATE TABLE metric_qualifications(metric_id TEXT NOT NULL REFERENCES metric_facts(metric_id),qualification_key TEXT NOT NULL CHECK(qualification_key IN('ATTRIBUTION','METER_SUPPORT','SCOPE','EXCLUDES','TIMEBASE','VISIBILITY','RAW_BUFFER_STATE')),exact_value TEXT NOT NULL,source_pointer TEXT NOT NULL,source_grade TEXT NOT NULL CHECK(source_grade IN('SOURCE_POINTER_EXACT','OFFLINE_RULE_EXACT','SOURCE_REPORTED_ONLY','ABSTAIN_UNAVAILABLE')),PRIMARY KEY(metric_id,qualification_key,exact_value)) STRICT,WITHOUT ROWID;
CREATE TABLE metrics_seal(singleton INTEGER PRIMARY KEY CHECK(singleton=1),projection_id TEXT NOT NULL CHECK(length(projection_id)=64),evidence_database_sha256 TEXT NOT NULL CHECK(length(evidence_database_sha256)=64),ddl_sha256 TEXT NOT NULL CHECK(length(ddl_sha256)=64),adapter_sha256 TEXT NOT NULL CHECK(length(adapter_sha256)=64),extractor_sha256 TEXT NOT NULL CHECK(length(extractor_sha256)=64),rational_math_sha256 TEXT NOT NULL CHECK(length(rational_math_sha256)=64),relational_export_sha256 TEXT NOT NULL CHECK(length(relational_export_sha256)=64),sample_count INTEGER NOT NULL CHECK(sample_count>=0),raw_verified_sample_count INTEGER NOT NULL CHECK(raw_verified_sample_count>=0),interval_count INTEGER NOT NULL CHECK(interval_count>=0),adjudication_count INTEGER NOT NULL CHECK(adjudication_count>=0),metric_count INTEGER NOT NULL CHECK(metric_count>=0),qualification_count INTEGER NOT NULL CHECK(qualification_count>=0),authority_vector TEXT NOT NULL CHECK(authority_vector='00000000'),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0)) STRICT;
CREATE VIEW presentation_authority_boundary AS SELECT authority_vector,authoritative,may_feed_controller,prose_may_supply_fact,unavailable_behavior FROM projection_policy WHERE singleton=1;
CREATE VIEW qualified_energy_metrics AS SELECT m.metric_id,m.interval_id,m.metric_name,m.bound_kind,m.numerator_text,m.denominator_text,m.unit,m.approximation_text,m.source_grade,m.premise_state FROM metric_facts m WHERE m.metric_name IN('delta_energy_nj','delta_energy_joules','delta_energy_ergs','power_w_lower','power_w_estimated','power_w_upper');
CREATE TRIGGER projection_policy_no_update BEFORE UPDATE ON projection_policy BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER projection_policy_no_delete BEFORE DELETE ON projection_policy BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER projection_policy_no_insert_after_seal BEFORE INSERT ON projection_policy WHEN EXISTS(SELECT 1 FROM metrics_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
